+            ) {
+                return null;
+            }
+        }
+        try {
+            $value = @unserialize($payload, ['allowed_classes' => $classes]);
+
+            return is_object($value) ? $value : null;
+        } catch (Throwable) {
+            return null;
+        }
+    }
